CREATE TABLE IF NOT EXISTS alert_rules(id UUID PRIMARY KEY,organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,name VARCHAR(160) NOT NULL,metric VARCHAR(80) NOT NULL,operator VARCHAR(10) NOT NULL,threshold DOUBLE PRECISION NOT NULL,consecutive_failures INTEGER NOT NULL DEFAULT 1,severity VARCHAR(30) NOT NULL DEFAULT 'WARNING',enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_alert_rules_org_enabled ON alert_rules(organization_id,enabled);